tool_input.command:
cat > /tmp/test-custom-metric.js << 'EOF'
import { Eval } from '../packages/frai-core/src/index.js';

const customMetric = {
  id: 'custom_metric',
  evaluate: (outputs) => ({
    id: 'custom_metric',
    label: 'Custom Metric',
    score: outputs.length > 0 ? 0.75 : null,
    total: outputs.length
  })
};

const evaluations = Eval.runEvaluations({
  outputs: ['test'],
  references: [],
  metrics: [Eval.exactMatchMetric, customMetric]
});

console.log('Evaluations:', JSON.stringify(evaluations, null, 2));

const report = Eval.generateReport({
  evaluations,
  outputsPath: './outputs.json',
  referencesPath: null,
  thresholds: {
    custom_metric: 0.7
  }
});

console.log('Report passed:', report.passed);
console.log('Thresholds:', JSON.stringify(report.thresholds, null, 2));
EOF
node /tmp/test-custom-metric.js
